{"cards": [{"node_code": "N_e15f580d3d98e111", "definition": "研究道路工程基础科学原理的学科，涵盖道路结构力学、路面材料性能、路基稳定性、交通荷载作用机理及道路系统规划理论。", "boundary": "本节点聚焦于“理论”与“原理”，区别于具体的工程实践。边界在于区分“理论分析”与“具体设计/施工”：侧重数学模型、物理机制、力学推导及通用原理归本节点；侧重具体项目的设计参数、施工工艺流程、材料配比应用归入相应工程节点。", "includes": ["道路结构力学与荷载分析理论", "路面材料本构关系与性能演化机理", "路基稳定性与土力学基础理论"], "excludes": ["具体道路项目的勘测、设计与施工技术方案", "道路建筑材料的具体生产工艺与配方"], "sibling_distinctions": [{"other_code": "N_d855da26c76a2e26", "rule": "区分依据为抽象层级：本节点收录指导设计的通用原理与模型；兄弟节点收录具体的规划方法、勘测技术与设计流程。"}, {"other_code": "N_af09c61bc45b8198", "rule": "区分依据为研究视角：本节点侧重材料在道路结构中的力学行为与理论性能；兄弟节点侧重材料本身的性质、分类、生产及试验方法。"}], "cross_boundary_rule": "若内容涉及基于理论推导的新结构设计方法，侧重理论创新归本节点，侧重工程应用归设计节点。"}, {"node_code": "N_d855da26c76a2e26", "definition": "涵盖公路建设前期的规划、勘测及设计全过程，包括公路网规划、地形地质勘测、线路选线、平纵横断面设计、制图及计算机辅助设计技术。", "boundary": "本节点聚焦于“建设前”的技术准备与设计工作。边界在于区分“设计”与“施工”：侧重方案确定、图纸绘制、参数计算归本节点；侧重现场作业、机械操作、质量控制归施工节点。区分“规划”与“管理”：侧重技术布局归本节点，侧重行政与经济政策归管理节点。", "includes": ["公路网规划、选线及线路平纵横断面设计", "道路工程勘测技术（地形、地质、水文）", "道路工程制图、技术资料编制及CAD/BIM等计算机辅助设计"], "excludes": ["道路施工、养护与维修的具体工程技术", "道路工程基础理论推导与力学模型研究"], "sibling_distinctions": [{"other_code": "N_a89f7cfa5e18d093", "rule": "区分依据为工程阶段：本节点为施工前的设计与准备；兄弟节点为施工阶段的现场作业与技术。"}, {"other_code": "N_e15f580d3d98e111", "rule": "区分依据为内容性质：本节点为应用性设计方法与技术；兄弟节点为支撑设计的科学原理与理论。"}], "cross_boundary_rule": "若内容涉及设计中的理论计算，侧重设计流程与规范应用归本节点，侧重理论模型创新归理论节点。"}, {"node_code": "N_af09c61bc45b8198", "definition": "研究用于道路工程的各种材料，包括路基土、路面沥青混合料、水泥混凝土、土工合成材料等的性质、分类、生产、试验及质量控制。", "boundary": "本节点聚焦于“材料”本身及其在道路工程中的应用特性。边界在于区分“材料”与“结构”：侧重材料成分、性能指标、试验方法归本节点；侧重材料在路面结构中的组合、厚度计算归路基路面工程节点。区分“材料”与“施工”：侧重材料生产与检验归本节点，侧重材料摊铺、压实工艺归施工节点。", "includes": ["路基土、沥青、水泥、集料等基础材料性质与分类", "路面混合料（沥青混合料、水泥混凝土）配合比设计与性能", "土工合成材料、新型道路材料及其试验检测技术"], "excludes": ["道路结构力学分析与理论模型", "道路施工机械操作与现场施工工艺"], "sibling_distinctions": [{"other_code": "N_ee65221d84c73e38", "rule": "区分依据为对象层级：本节点侧重单一材料或混合料的性能；兄弟节点侧重由材料组成的路基、路面整体结构设计与施工。"}, {"other_code": "N_e15f580d3d98e111", "rule": "区分依据为研究深度：本节点侧重材料工程应用与试验；兄弟节点侧重材料微观机理与宏观力学理论。"}], "cross_boundary_rule": "若内容涉及材料在特定结构中的性能表现，侧重材料本身特性归本节点，侧重结构整体响应归路基路面工程节点。"}]}
